con:config.script:
// Функции генерации
function generateRandomName() {
    var firstNames = ["Алексей","Дмитрий","Мария","Екатерина","Иван","Анна","Павел","Ольга"];
    var lastNames  = ["Иванов","Петров","Сидоров","Кузнецов","Смирнов","Попов","Лебедев","Козлов"];
    var first = firstNames[Math.floor(Math.random() * firstNames.length)];
    var last  = lastNames[Math.floor(Math.random() * lastNames.length)];
    return first + " " + last;
}

function generateRandomEmail() {
    var domains = ["gmail.com","yahoo.com","mail.ru","yandex.ru","outlook.com","example.com"];
    var chars = "abcdefghijklmnopqrstuvwxyz0123456789";
    var username = "";
    for (var i = 0; i < 10; i++) {
        username += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    var domain = domains[Math.floor(Math.random() * domains.length)];
    return username + "@" + domain;
}

function generateRandomPassword() {
    var chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%";
    var password = "";
    for (var i = 0; i < 12; i++) {
        password += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return password;
}

// Генерация
var randomName = generateRandomName();
var randomEmail = generateRandomEmail();
var randomPassword = generateRandomPassword();

// Сохранение на уровне проекта
var project = testRunner.testCase.testSuite.project;
project.setPropertyValue("savedName", randomName);
project.setPropertyValue("savedEmail", randomEmail);
project.setPropertyValue("savedPassword", randomPassword);

// Логирование
log.info("Сгенерировано:");
log.info("Name: " + randomName);
log.info("Email: " + randomEmail);
log.info("Password: " + randomPassword);

// Получаем тест-кейс
var testCase = testRunner.testCase;
var stepList = testCase.getTestStepList();

if (stepList.size() <= 1) {
    throw new Error("В тест-кейсе нет запроса!");
}

// Находим первый REST-запрос (не обязательно индекс 1)
var requestName = null;
for (var i = 0; i < stepList.size(); i++) {
    var step = stepList.get(i);
    if (step.getClass().toString().indexOf("RestTestRequestStep") > -1) {
        requestName = step.getName();
        log.info("Найден REST-запрос на шаге " + i + ": '" + requestName + "'");
        break;
    }
}

if (!requestName) {
    throw new Error("Не найден REST-запрос в тест-кейсе!");
}

// Получаем статус и ответ
var statusCode = context.expand('${' + requestName + '#ResponseStatusCode}');
var responseBody = context.expand('${' + requestName + '#Response}');

log.info("Статус код: '" + statusCode + "'");
log.info("Длина ответа: " + responseBody.length);

if (responseBody === '') {
    log.error("ОТВЕТ ПУСТОЙ!");
    log.error("Проверьте, выполнился ли запрос '" + requestName + "'");
    log.error("Статус код: " + statusCode);

    // Пробуем выполнить запрос принудительно?
    // Но лучше остановиться и показать ошибку
    throw new Error("Запрос не вернул ответ");
}

// Если ответ не пустой, извлекаем токен
try {
    log.info("Ответ: " + responseBody);

    // Извлекаем токен через регулярное выражение
    var tokenMatch = responseBody.match(/"token"\s*:\s*"([^"]+)"/);

    if (tokenMatch && tokenMatch[1]) {
        var token = tokenMatch[1];
        log.info("✓ token найден: " + token);

        // Сохраняем
        testRunner.testCase.testSuite.project.setPropertyValue("token", token);
        log.info("✓ token сохранен в token");

        // Проверяем
        var savedToken = testRunner.testCase.testSuite.project.getPropertyValue("token");
        log.info("✓ Проверка: token = " + savedToken);
    } else {
        log.error("token не найден в ответе");
        log.error("Ответ: " + responseBody);
    }
} catch (e) {
    log.error("Ошибка: " + e.message);
}

// Получаем тест-кейс
var testCase = testRunner.testCase;
var stepList = testCase.getTestStepList();

if (stepList.size() <= 1) {
    throw new Error("В тест-кейсе нет запроса!");
}

// Находим первый REST-запрос (не обязательно индекс 1)
var requestName = null;
for (var i = 0; i < stepList.size(); i++) {
    var step = stepList.get(i);
    if (step.getClass().toString().indexOf("RestTestRequestStep") > -1) {
        requestName = step.getName();
        log.info("Найден REST-запрос на шаге " + i + ": '" + requestName + "'");
        break;
    }
}

if (!requestName) {
    throw new Error("Не найден REST-запрос в тест-кейсе!");
}

// Получаем статус и ответ
var statusCode = context.expand('${' + requestName + '#ResponseStatusCode}');
var responseBody = context.expand('${' + requestName + '#Response}');

log.info("Статус код: '" + statusCode + "'");
log.info("Длина ответа: " + responseBody.length);

if (responseBody === '') {
    log.error("ОТВЕТ ПУСТОЙ!");
    log.error("Проверьте, выполнился ли запрос '" + requestName + "'");
    log.error("Статус код: " + statusCode);

    // Пробуем выполнить запрос принудительно?
    // Но лучше остановиться и показать ошибку
    throw new Error("Запрос не вернул ответ");
}

// Если ответ не пустой, извлекаем токен
try {
    log.info("Ответ: " + responseBody);

    // Извлекаем токен через регулярное выражение
    var userIdMatch = responseBody.match(/"id"\s*:\s*"([^"]+)"/);

    if (userIdMatch && userIdMatch[1]) {
        var userId = userIdMatch[1];
        log.info("✓ userId найден: " + userId);

        // Сохраняем
        testRunner.testCase.testSuite.project.setPropertyValue("userId", userId);
        log.info("✓ userId сохранен в userId");

        // Проверяем
        var savedUserId = testRunner.testCase.testSuite.project.getPropertyValue("userId");
        log.info("✓ Проверка: userId = " + savedUserId);
    } else {
        log.error("userId не найден в ответе");
        log.error("Ответ: " + responseBody);
    }
} catch (e) {
    log.error("Ошибка: " + e.message);
}

